#ifndef P0N_BROWSER_LAB_HTML_H
#define P0N_BROWSER_LAB_HTML_H

static const char P0N_BROWSER_LAB_HTML[] =
  "<!doctype html>\n"
  "<meta charset=\"utf-8\">\n"
  "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"
  "<title>Xensonar Native Browser Lab</title>\n"
  "<style>\n"
  "html,body{background:#0b0d10;color:#e9edf2;font:15px/1.45 system-ui,sans-serif;margin:0}main{max-width:820px;margin:32px auto;padding:24px}.card{background:#15191f;border:1px solid #2c3440;border-radius:14px;padding:20px}h1{font-size:24px;margin:0 0 8px}#status{font-weight:700}.ok{color:#78e08f}.bad{color:#ff7b7b}pre{white-space:pre-wrap;background:#090b0e;padding:14px;border-radius:10px;min-height:160px}button{padding:10px 14px;margin:5px;background:#242b34;color:#fff;border:1px solid #46515f;border-radius:8px}\n"
  "</style>\n"
  "<main><div class=\"card\"><h1>Xensonar Native Browser Lab</h1><p id=\"status\">Running browser → adapter → sidecar → Native RT checks…</p><div><button id=\"tone\">Fresh attack</button><button id=\"panic\">Panic</button></div><pre id=\"log\"></pre></div></main>\n"
  "<script src=\"/xensonar-native-protocol.js\"></script>\n"
  "<script src=\"/xensonar-native-control.js\"></script>\n"
  "<script>\n"
  "(()=>{'use strict';\n"
  "const logEl=document.querySelector('#log'),statusEl=document.querySelector('#status');\n"
  "const log=(s)=>{logEl.textContent+=s+'\\n'};const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));\n"
  "const progress=(stage)=>fetch('/v1/browser-progress',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'stage='+stage,cache:'no-store'}).catch(()=>null);\n"
  "progress(1);\n"
  "const ctl=new XensonarNativeControl({initialSequence:900,initialRevision:99});progress(2);\n"
  "async function waitFor(pred,ms=1200){const end=performance.now()+ms;let s=null;while(performance.now()<end){s=await ctl.status();if(pred(s))return s;await sleep(20)}return s}\n"
  "async function freshAttack(freq=440){const before=await ctl.status(),started=Number(before.transportStarted);const eventTime=performance.now();const r=await ctl.attack({slot:73,generation:1,frequencyHz:freq,peak:0.02,gestureTimeMs:eventTime});const after=await waitFor(s=>Number(s.transportStarted)>=started+1);return !!r.ok&&after&&Number(after.transportStarted)>=started+1}\n"
  "document.querySelector('#tone').onclick=()=>freshAttack(440);document.querySelector('#panic').onclick=()=>ctl.panic();\n"
  "async function report(pass,checks,failed,clockRttUs,finalRevision){const body=`pass=${pass?1:0}&checks=${checks}&failed=${failed}&clockRttUs=${clockRttUs}&finalRevision=${finalRevision}`;return fetch('/v1/browser-report',{method:'POST',headers:{'X-Xensonar-Token':window.__xensonarReportToken||'','Content-Type':'application/x-www-form-urlencoded'},body,cache:'no-store'})}\n"
  "async function run(){const checks={};let clockRttUs=0,finalRevision=0;\n"
  "try{\n"
  " const ses=await ctl.connect({clockSamples:8,settleMs:8});await progress(3);checks.session=ctl.connected;checks.backendKnown=typeof ses.physicalAudio==='boolean';checks.quantum=Number(ses.deviceQuantumFrames)>0;clockRttUs=Math.round(ctl.clockRttMs*1000);checks.clockSync=ctl.clockRttMs<250;log(`session q=${ses.deviceQuantumFrames} cb=${ses.callbacks}`);log(`clock sync RTT ${ctl.clockRttMs.toFixed(3)} ms`);\n"
  " checks.heartbeat=!!(await ctl.heartbeat()).ok;await progress(4);\n"
  " checks.state100=!!(await ctl.publishState({rootHz:330,gain:0.75})).ok;\n"
  " const burst=[];for(let r=101;r<=116;r++)burst.push(ctl.publishState({rootHz:220+r,gain:0.5}));await Promise.all(burst);const st=await waitFor(s=>Number(s.mailboxRevision)>=116);finalRevision=Number(st&&st.mailboxRevision||0);checks.latestWins=finalRevision===116;await progress(5);\n"
  " checks.freshAttack=await freshAttack(440);await progress(6);\n"
  " checks.release=!!(await ctl.release({slot:73,generation:1})).ok;\n"
  " await ctl.heartbeat();const b=await ctl.status();await sleep(1000);const a=await ctl.status();checks.silenceProgress=Number(a.frame)>Number(b.frame)&&Number(a.callbacks)>Number(b.callbacks);checks.noBacklog=Number(a.queueDepth)===Number(b.queueDepth)&&Number(a.transportStarted)===Number(b.transportStarted);checks.noDeviceFault=Number(a.xrunCount)===Number(b.xrunCount)&&Number(a.processErrors)===Number(b.processErrors);await progress(7);await ctl.heartbeat();\n"
  " await ctl.syncClock({samples:8,settleMs:8});const staleGesture=performance.now();const pre=await ctl.status();const stale0=Number(pre.transportStale),start0=Number(pre.transportStarted);await sleep(250);const sr=await ctl.attack({slot:74,generation:1,frequencyHz:523.25,peak:0.02,gestureTimeMs:staleGesture});const sa=await waitFor(s=>Number(s.transportStale)>=stale0+1);checks.staleIngress=!!sr.ok;checks.staleDropped=!!sa&&Number(sa.transportStale)>=stale0+1&&Number(sa.transportStarted)===start0;await progress(8);\n"
  " checks.panic=!!(await ctl.panic()).ok;const pan=await waitFor(s=>Number(s.ownerClosed)===1);checks.panicTerminal=!!pan&&Number(pan.ownerClosed)===1;await progress(9);\n"
  " const failed=Object.entries(checks).filter(([,v])=>!v).map(([k])=>k),pass=failed.length===0;log(JSON.stringify(checks,null,2));statusEl.textContent=pass?'PASS — browser → adapter → sidecar → Native RT':'FAIL — '+failed.join(', ');statusEl.className=pass?'ok':'bad';\n"
  " // Report via adapter-private token endpoint helper exposed only for this lab lifecycle.\n"
  " const reportBody=`pass=${pass?1:0}&checks=${Object.keys(checks).length}&failed=${failed.length}&clockRttUs=${clockRttUs}&finalRevision=${finalRevision}`;\n"
  " await ctl._labReport(reportBody);await progress(10);await sleep(120);await ctl.shutdown();\n"
  " }catch(e){statusEl.textContent='FAIL — '+e;statusEl.className='bad';log(String(e));try{await ctl._labReport('pass=0&checks=0&failed=1&clockRttUs=0&finalRevision=0');await ctl.shutdown()}catch{}}\n"
  "}\n"
  "run();\n"
  "})();\n"
  "</script>\n";

#endif
